import java.util.concurrent.BrokenBarrierException;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.CyclicBarrier;
import java.util.concurrent.Semaphore;
import java.util.concurrent.atomic.AtomicInteger;

public class Main {
    public static void main(String[] args) throws Exception {
        demoCountDownLatch();
        demoCyclicBarrier();
        demoSemaphore();
    }

    static void demoCountDownLatch() throws InterruptedException {
        CountDownLatch done = new CountDownLatch(3);
        AtomicInteger loaded = new AtomicInteger();
        for (int i = 0; i < 3; i++) {
            final int part = i + 1;
            new Thread(() -> {
                try {
                    loaded.addAndGet(part);
                } finally {
                    done.countDown();
                }
            }, "loader-" + part).start();
        }
        done.await();
        System.out.println("latch loaded=" + loaded.get());
        assert loaded.get() == 6;
    }

    static void demoCyclicBarrier() throws InterruptedException {
        AtomicInteger completedPhases = new AtomicInteger();
        CyclicBarrier barrier = new CyclicBarrier(3, completedPhases::incrementAndGet);
        CountDownLatch finished = new CountDownLatch(3);
        for (int i = 0; i < 3; i++) {
            final int worker = i;
            new Thread(() -> {
                try {
                    for (int phase = 0; phase < 2; phase++) {
                        doPhaseWork(worker, phase);
                        barrier.await();
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                } catch (BrokenBarrierException e) {
                    throw new IllegalStateException("barrier generation failed", e);
                } finally {
                    finished.countDown();
                }
            }, "barrier-worker-" + worker).start();
        }
        finished.await();
        System.out.println("barrier phases=" + completedPhases.get());
        assert completedPhases.get() == 2;
    }

    static void doPhaseWork(int worker, int phase) {
        if (worker == 0 && phase == 0) {
            Thread.yield();
        }
    }

    static void demoSemaphore() throws InterruptedException {
        Semaphore permits = new Semaphore(2);
        AtomicInteger active = new AtomicInteger();
        AtomicInteger maxActive = new AtomicInteger();
        CountDownLatch finished = new CountDownLatch(5);
        for (int i = 0; i < 5; i++) {
            new Thread(() -> {
                boolean acquired = false;
                try {
                    permits.acquire();
                    acquired = true;
                    int now = active.incrementAndGet();
                    maxActive.accumulateAndGet(now, Math::max);
                    Thread.sleep(20);
                    active.decrementAndGet();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                } finally {
                    if (acquired) {
                        permits.release();
                    }
                    finished.countDown();
                }
            }, "semaphore-user-" + i).start();
        }
        finished.await();
        System.out.println("semaphore maxActive=" + maxActive.get());
        assert maxActive.get() <= 2;
        assert permits.availablePermits() == 2;
    }
}
